int maxSubArray(vector<int>& a) {
    int cur = a[0], best = a[0];
    for (int i = 1; i < (int)a.size(); ++i) {
        cur = max(a[i], cur + a[i]);
        best = max(best, cur);
    }
    return best;
}

def max_subarray(a):
    cur = best = a[0]
    for x in a[1:]:
        cur = max(x, cur + x)      # extend the run, or restart at x
        best = max(best, cur)
    return best

class Solution {
public:
    int maxSubArray(vector<int>& a) {
        int cur = a[0], best = a[0];
        for (int i = 1; i < (int)a.size(); i++) {
            cur = max(a[i], cur + a[i]);
            best = max(best, cur);
        }
        return best;
    }
};

class Solution:
    def maxSubArray(self, a: list[int]) -> int:
        cur = best = a[0]
        for x in a[1:]:
            cur = max(x, cur + x)
            best = max(best, cur)
        return best

class Solution {
public:
    int maxProduct(vector<int>& a) {
        int mx = a[0], mn = a[0], best = a[0];
        for (int i = 1; i < (int)a.size(); i++) {
            if (a[i] < 0) swap(mx, mn);
            mx = max(a[i], mx * a[i]);
            mn = min(a[i], mn * a[i]);
            best = max(best, mx);
        }
        return best;
    }
};

class Solution:
    def maxProduct(self, a: list[int]) -> int:
        mx = mn = best = a[0]
        for x in a[1:]:
            if x < 0:
                mx, mn = mn, mx
            mx = max(x, mx * x)
            mn = min(x, mn * x)
            best = max(best, mx)
        return best

class Solution {
public:
    int maxSubarraySumCircular(vector<int>& a) {
        int total = 0, curMax = 0, bestMax = INT_MIN, curMin = 0, bestMin = INT_MAX;
        for (int x : a) {
            total += x;
            curMax = max(x, curMax + x); bestMax = max(bestMax, curMax);
            curMin = min(x, curMin + x); bestMin = min(bestMin, curMin);
        }
        if (bestMax < 0) return bestMax;          // all negative
        return max(bestMax, total - bestMin);
    }
};

class Solution:
    def maxSubarraySumCircular(self, a: list[int]) -> int:
        total = 0
        cur_max = best_max = a[0]
        cur_min = best_min = a[0]
        for i, x in enumerate(a):
            total += x
            if i == 0:
                continue
            cur_max = max(x, cur_max + x); best_max = max(best_max, cur_max)
            cur_min = min(x, cur_min + x); best_min = min(best_min, cur_min)
        if best_max < 0:
            return best_max
        return max(best_max, total - best_min)

class Solution {
public:
    int maxProfit(vector<int>& p) {
        int minPrice = INT_MAX, best = 0;
        for (int x : p) { minPrice = min(minPrice, x); best = max(best, x - minPrice); }
        return best;
    }
};

class Solution:
    def maxProfit(self, prices: list[int]) -> int:
        min_price, best = float('inf'), 0
        for x in prices:
            min_price = min(min_price, x)
            best = max(best, x - min_price)
        return best

class Solution {
public:
    int maxRectangleSum(vector<vector<int>>& m) {
        int R = m.size(), C = m[0].size(), best = INT_MIN;
        for (int top = 0; top < R; top++) {
            vector<int> col(C, 0);
            for (int bot = top; bot < R; bot++) {
                for (int c = 0; c < C; c++) col[c] += m[bot][c];
                int cur = col[0], local = col[0];
                for (int c = 1; c < C; c++) { cur = max(col[c], cur + col[c]); local = max(local, cur); }
                best = max(best, local);
            }
        }
        return best;
    }
};

class Solution:
    def maxRectangleSum(self, m: list[list[int]]) -> int:
        R, C = len(m), len(m[0])
        best = float('-inf')
        for top in range(R):
            col = [0] * C
            for bot in range(top, R):
                for c in range(C):
                    col[c] += m[bot][c]
                cur = local = col[0]
                for c in range(1, C):
                    cur = max(col[c], cur + col[c])
                    local = max(local, cur)
                best = max(best, local)
        return best
